return [{ json: {
  pipeline: "Prospection Résonance",          // nom exact du pipeline Pipedrive
  gemini_model: "gemini-flash-latest, gemini-flash-lite-latest", // un ou plusieurs modèles Google AI Studio, séparés par des virgules (répartition de la charge)
  pipedrive_base: "https://api.pipedrive.com/v1",
  gemini_base: "https://generativelanguage.googleapis.com/v1beta",
  gmail_base: "https://gmail.googleapis.com/gmail/v1/users/me",
  signataire: "Prénom Nom",                    // personne qui signe les emails
  emails_fondatrices: "",                      // adresses qui reçoivent alertes, arbitrage du lundi et export (séparées par des virgules ; vide = la boîte connectée)
  lien_rdv: "COLLER_ICI_LE_LIEN_DE_PRISE_DE_RENDEZ-VOUS",
  plafond_hebdo: 35,                           // premiers messages par semaine au maximum
  // Veille (agent 1)
  flux_rss: [ "COLLER_ICI_UNE_URL_DE_FLUX_RSS" ], // par exemple des flux Google Alertes
  label_veille: "veille",                      // libellé Gmail des newsletters et alertes à analyser
  fenetre_heures: 48,                          // âge maximal d'un article RSS
  max_articles: 25,
  // Bibliothèque de preuves validée par les fondatrices.
  // origine « À valider » = bloque le brouillon ; une phrase entre crochets est aussi bloquée par le contrôle automatique.
  preuves: [
    { id: "vins", segment: "Vins & Spiritueux", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "beaute", segment: "Beauté & Parfumerie", origine: "Projet Anna & Louise", phrase: "[Phrase de preuve validée : projet réalisé pour une maison de ce segment]" },
    { id: "joaillerie", segment: "Joaillerie & Horlogerie", origine: "Expérience des fondatrices (autre structure)", phrase: "[Phrase de preuve validée : expérience antérieure des fondatrices]" },
    { id: "mode", segment: "Mode & Maroquinerie", origine: "À valider", phrase: "[Phrase de preuve en attente de validation]" }
  ],
  // Emails des fondatrices ou de l'agence ayant obtenu une réponse (modèles de style de l'agent 4)
  exemples_valides: []
}}];

return [{ json: { texte: "Tu es l'agent 2 · Identification et enrichissement de Résonance (Anna & Louise : stratégie de marque, direction créative, image, IA générative, pour le luxe et le premium).
À partir UNIQUEMENT de la fiche fournie (signal vérifié, maison, poste du contact), réponds :
- "adequation" : le besoin probable couvert par le studio, UNE valeur parmi : "Stratégie, création et IA" | "Direction créative ou image" | "IA générative seule" | "Éditorial ou social" | "Aucune" ;
- "hypothese" : l'enjeu probable du décideur, en une phrase qui commence par « Hypothèse : » et reste une supposition ;
- "fonction" : "Image" | "Marketing" | "Brand" | "Digital" | "Communication" | "Autre" (d'après le poste) ;
- "niveau_decision" : "Direction" (Directeur·rice, CMO, Managing Director) | "Head / VP" | "Manager" | "Chef de projet" | "Hors cible".
Réponds uniquement avec ce JSON : {"adequation": "", "hypothese": "Hypothèse : ", "fonction": "", "niveau_decision": ""}" } }];

// Carte des champs et étapes Pipedrive, retrouvés par leur NOM exact
