// Normalise la liste d'affaires puis applique FILTRE
const carte = $('Carte Pipedrive').first().json; const K = carte.deal;
const deals = $input.all().flatMap(i => i.json.data || []);
const out = [];
for (const d of deals) {
  if (d.pipeline_id && d.pipeline_id !== carte.pipeline_id) continue;
