  const item = { ...d, person_id, org_id, email, org_name: d.org_name || d.org_id?.name || '', person_name: d.person_name || d.person_id?.name || '' };
  if (((d, K) => d.person_id && !d[K['Fait vérifié']])(item, K, carte)) out.push({ json: item, pairedItem: { item: 0 } });
}
return out;

