const fonctionDe = poste => { const p = norm(poste); if (/image|artisti|creati/.test(p)) return 'Image'; if (/brand|marque/.test(p)) return 'Brand'; if (/digital|innovation|numerique/.test(p)) return 'Digital'; if (/communication|comms|presse|pr /.test(p + ' ')) return 'Communication'; if (/marketing|cmo|managing director|directeur general|directrice generale|general manager/.test(p)) return 'Marketing'; return 'Autre'; };
const gem = j => { try { return JSON.parse(j.candidates?.[0]?.content?.parts?.[0]?.text); } catch (e) { return null; } };

const carte = $('Carte Pipedrive').first().json; const K = carte.deal, KP = carte.person; const cfg = $('CONFIG').first().json;
const d = $('À enrichir').item.json;
const p = $('Lire personne').item.json.data || {};
const autresPers = ($('Affaires de la personne').item.json.data || []).filter(x => x.id !== d.id);
const maison = ($('Affaires de la maison').item.json.data || []).filter(x => x.id !== d.id && x.status === 'open');
const notes = $('Notes affaire').item.json.data || [];
const g = gem($('Gemini · enrichir').item.json) || {};
// 1. Données du signal (champs, sinon note de l'agent 1)
const txt = (notes.map(x => String(x.content || '')).find(c => c.includes('Signal Résonance')) || '').replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
const lit = lab => { const m = txt.match(new RegExp(lab + '\\s*:\\s*(.+)')); return m ? m[1].trim().replace(/^«\s*|\s*»$/g, '') : ''; };
const url = val(d, K['URL source']) || lit('URL source');
const extrait = val(d, K['Extrait source']) || lit('Extrait');
// 2. Contrôle automatique du fait (texte visible + contenu des scripts, accents et apostrophes décodés)
const brut = String($json.data ?? $json.body ?? (typeof $json === 'string' ? $json : ''));
const ENT = { nbsp: ' ', rsquo: "'", lsquo: "'", laquo: '"', raquo: '"', ldquo: '"', rdquo: '"', amp: '&', quot: '"', apos: "'", eacute: 'é', egrave: 'è', ecirc: 'ê', agrave: 'à', acirc: 'â', ccedil: 'ç', ocirc: 'ô', ucirc: 'û', icirc: 'î', iuml: 'ï', euml: 'ë', ugrave: 'ù', hellip: '...', ndash: '-', mdash: '-' };
const clair = s => s.replace(/\\u([0-9a-fA-F]{4})/g, (m, h) => String.fromCharCode(parseInt(h, 16))).replace(/\\n|\\r|\\t|\\"/g, ' ')
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16))).replace(/&([a-z]+);/gi, (m, e) => ENT[e.toLowerCase()] ?? ' ');
const plat = s => norm(clair(s)).replace(/[’‘`´]/g, "'").replace(/[^a-z0-9'@.-]+/g, ' ').replace(/\s+/g, ' ').trim();
const page = plat(brut.replace(/<[^>]+>/g, ' '));
const ext = plat(extrait);
const mots = ext.split(' ').filter(w => w.length > 2);
const trouves = mots.filter(w => page.includes(w)).length;
let fait;
if (!url || !extrait) fait = 'Échec : URL ou extrait manquant';
else if (!page) fait = 'À vérifier manuellement : page inaccessible (payante ou protégée)';
else if (page.includes(ext)) fait = 'Vérifié : « ' + extrait + ' »';
else if (mots.length && trouves / mots.length >= 0.85) fait = 'Vérifié (formulation proche) : « ' + extrait + ' »';
else fait = 'À vérifier manuellement : extrait non retrouvé dans la page (' + trouves + '/' + mots.length + ' mots)';
const factOk = fait.startsWith('Vérifié');
// 3. Exclusions
const exclusions = [];
if (norm(val(p, KP['Opposition'])).startsWith('oui')) exclusions.push('opposition enregistrée');
const recent = autresPers.find(x => (val(x, K['Date premier envoi']) && (Date.now() - new Date(val(x, K['Date premier envoi'])).getTime()) < 183 * 864e5) || (x.status === 'open' && [carte.stage['Contacté'], carte.stage['À relancer'], carte.stage['Conversation ouverte'], carte.stage['Rendez-vous']].includes(x.stage_id)));
if (recent) exclusions.push('contact déjà sollicité ou en conversation (affaire ' + recent.id + ')');
if (autresPers.some(x => x.status === 'won')) exclusions.push('client actif');
const coordination = maison.filter(x => [carte.stage['Prêt à contacter'], carte.stage['Contacté'], carte.stage['À relancer'], carte.stage['Conversation ouverte']].includes(x.stage_id)).map(x => (x.person_name || 'contact') + ' (affaire ' + x.id + ', angle ' + (val(x, K['Angle']) || '—') + ')');
// 4. Preuve la plus proche (bibliothèque validée)
const cat = val(d, K['Catégorie']) || lit('Catégorie');
const preuve = val(d, K['Preuve A&L']) || (cfg.preuves.find(x => norm(x.segment) === norm(cat) && !norm(x.origine).startsWith('a valider')) || {}).id || '';
// 5. Écritures
const body = { [K['Fait vérifié']]: fait, [K['Hypothèse']]: g.hypothese || '', [K['Adéquation expertises']]: g.adequation || '', [K['Fin de conservation']]: plusMois(36) };
if (!val(d, K['URL source']) && url) body[K['URL source']] = url;
if (!val(d, K['Extrait source']) && extrait) body[K['Extrait source']] = extrait;
if (!val(d, K['Type de signal']) && lit('Type de signal')) body[K['Type de signal']] = lit('Type de signal');
if (!val(d, K['Date de publication']) && lit('Date de publication')) body[K['Date de publication']] = lit('Date de publication');
if (!val(d, K['Catégorie']) && cat) body[K['Catégorie']] = cat;
if (!val(d, K['Résumé du signal']) && lit('Résumé')) body[K['Résumé du signal']] = lit('Résumé');
if (preuve && !val(d, K['Preuve A&L'])) body[K['Preuve A&L']] = preuve;
if (exclusions.length) { body.status = 'lost'; body.lost_reason = ('Exclu : ' + exclusions.join(' ; ')).slice(0, 150); }
else if (factOk) body.stage_id = carte.stage['À qualifier'];
const person_body = {};
if (!val(p, KP['Niveau de décision']) && g.niveau_decision) person_body[KP['Niveau de décision']] = g.niveau_decision;
if (!val(p, KP['Fiabilité email'])) person_body[KP['Fiabilité email']] = d.email ? 'À confirmer' : 'Manquant';
if (!val(p, KP['Provenance coordonnées'])) person_body[KP['Provenance coordonnées']] = 'Saisie manuelle ou Sales Navigator (' + today() + ')';
const note_html = '<b>Fiche compte (agent 2)</b><br>Fait : ' + esc(fait) + '<br>' + esc(g.hypothese || 'Hypothèse : —') + '<br>Adéquation : ' + esc(g.adequation || '—') + ' · Fonction : ' + esc(g.fonction || fonctionDe(val(p, KP['Poste']))) +
  '<br>Preuve proposée : ' + esc(preuve || 'aucune validée pour ce segment') +
  (coordination.length ? '<br><b>Coordination</b> : autre contact en séquence dans la maison : ' + esc(coordination.join(' ; ')) : '') +
  (exclusions.length ? '<br><b>Exclu</b> : ' + esc(exclusions.join(' ; ')) : factOk ? '<br>→ Passage à « À qualifier ».' : '<br>→ Reste « À rechercher » : aucun fait vérifié. Corriger l\'URL ou l\'extrait, puis vider le champ « Fait vérifié ».') +
  '<br><i>Validation humaine : confirmer l\'identité, le niveau de décision, et supprimer toute hypothèse fragile.</i>';
return { json: { deal_id: d.id, person_id: d.person_id, body, person_body, note_html } };
